class ConnectGame:
    def __init__(self, board):
        self.rows = [line.strip() for line in board.splitlines() if line.strip()]
        self.size = len(self.rows)

    def get_winner(self):
        if self.size == 0:
            return ""

        # X plays left to right; O plays top to bottom.
        if self._reaches("X", self._x_neighbors, (0, 0), self._on_right_edge):
            return "X"
        if self._reaches("O", self._o_neighbors, (0, 0), self._on_bottom_edge):
            return "O"
        return ""

    def _cell(self, row, col):
        if 0 <= row < self.size and 0 <= col < len(self.rows[row]):
            return self.rows[row][col]
        return None

    def _on_right_edge(self, row, col):
        return col == len(self.rows[row]) - 1

    def _on_bottom_edge(self, row, col):
        return row == self.size - 1

    def _x_neighbors(self, row, col):
        return [
            (row - 1, col),
            (row, col - 1),
            (row + 1, col),
            (row, col + 1),
        ]

    def _o_neighbors(self, row, col):
        return [
            (row - 1, col + 1),
            (row, col + 1),
            (row + 1, col),
            (row + 1, col + 1),
        ]

    def _reaches(self, player, neighbors, start, goal):
        seen = {start}
        stack = [start]
        while stack:
            row, col = stack.pop()
            if goal(row, col):
                return True
            for next_row, next_col in neighbors(row, col):
                if self._cell(next_row, next_col) != player:
                    continue
                if (next_row, next_col) in seen:
                    continue
                seen.add((next_row, next_col))
                stack.append((next_row, next_col))
        return False

class ConnectGame:
    def __init__(self, board):
        self.rows = [line.strip() for line in board.splitlines() if line.strip()]

    def get_winner(self):
        if not self.rows:
            return ""

        height = len(self.rows)
        width = len(self.rows[0])

        x_starts = [(row, 0) for row in range(height) if self._cell(row, 0) == "X"]
        if self._reaches("X", x_starts, lambda row, col: col == width - 1):
            return "X"

        o_starts = [(0, col) for col in range(width) if self._cell(0, col) == "O"]
        if self._reaches("O", o_starts, lambda row, col: row == height - 1):
            return "O"

        return ""

    def _cell(self, row, col):
        if 0 <= row < len(self.rows) and 0 <= col < len(self.rows[row]):
            return self.rows[row][col]
        return None

    @staticmethod
    def _neighbors(row, col):
        # The board is a slanted parallelogram: row `row` is indented by `row`
        # characters, so cell (row, col) sits at horizontal position row + 2*col.
        # A hexagonal cell touches the six cells one half-width away.
        return [
            (row, col - 1),
            (row, col + 1),
            (row - 1, col),
            (row - 1, col + 1),
            (row + 1, col - 1),
            (row + 1, col),
        ]

    def _reaches(self, player, starts, goal):
        seen = set()
        stack = []
        for start in starts:
            if start not in seen:
                seen.add(start)
                stack.append(start)

        while stack:
            row, col = stack.pop()
            if goal(row, col):
                return True
            for nrow, ncol in self._neighbors(row, col):
                if self._cell(nrow, ncol) != player:
                    continue
                if (nrow, ncol) in seen:
                    continue
                seen.add((nrow, ncol))
                stack.append((nrow, ncol))

        return False

